using FromZero;
using System.Text.Json;
static class PreparationLiveChecks
{
 public static async Task Run(string folder,Action<bool,string> check,bool downloads)
 {
  List<object> metadata=[];bool all=true;
  foreach(var app in PreparationExperience.Apps){var id=PreparationPackages.RecipeId(app.Id);Console.WriteLine("PREPARATION SOURCE: "+app.Name);try{var recipe=await PreparationPackages.ResolveAsync(id);var version=id.StartsWith("app-")?PreparationPackages.KnownTarget(id):await PreparationPackages.TargetVersionAsync(id,default);if(id=="prepare-vlc")version=ApplicationCatalog.Number(recipe.Name);if(id!="steam"&&version==null)throw new InvalidDataException("Target version missing");metadata.Add(new{Status="PASS",Id=id,Version=version?.ToString()??"Steam self-updater",recipe.Url,recipe.Publisher,recipe.Extension});check(!recipe.PublisherHashOnly&&!recipe.CatalogSigned&&recipe.Publisher.Length>0,"Live primary preparation source: "+app.Name+" "+version);}catch(Exception ex){all=false;metadata.Add(new{Status="FAIL",Id=id,Error=ex.Message});Console.WriteLine("SOURCE FAILED: "+app.Name+" / "+ex.Message);}}
  await File.WriteAllTextAsync(Path.Combine(folder,"preparation-experience-sources.json"),JsonSerializer.Serialize(metadata,LocalStore.Json));check(all,"Every curated automatic preparation source resolves from live primary metadata");
  if(downloads){List<object> packages=[];bool verified=true;foreach(var id in new[]{"app-git","app-node-lts","app-obs","app-keepassxc","app-audacity"})try{var recipe=await PreparationPackages.ResolveAsync(id);var file=await AppDownloads.DownloadAsync(recipe,new Progress<string>());var cached=AppDownloads.Cached(recipe)!;await AppDownloads.VerifyCachedAsync(recipe,cached);packages.Add(new{Status="PASS",Id=id,Record=cached});check(File.Exists(file.Path),"New preparation binary signature/hash verified without installation: "+id);}catch(Exception ex){verified=false;packages.Add(new{Status="FAIL",Id=id,Error=ex.Message});Console.WriteLine("BINARY FAILED: "+id+" / "+ex.Message);}await File.WriteAllTextAsync(Path.Combine(folder,"preparation-experience-downloads.json"),JsonSerializer.Serialize(packages,LocalStore.Json));check(verified,"Selected new preparation installers download and verify without execution");}
  var snapshot=await PreparationDiagnostics.CaptureAsync();var options=PreparationExperience.Profile("streaming") with{Apps=[],Games=["cs2","valorant","fortnite","gtav","minecraft","apex"]};var report=await PreparationDiagnostics.InspectAsync(options,snapshot);await File.WriteAllTextAsync(Path.Combine(folder,"preparation-readiness-verification.json"),JsonSerializer.Serialize(new{report.Checked,DeviceCount=snapshot.Devices.Count,AudioOutputs=snapshot.AudioOutputs.Count,AudioInputs=snapshot.AudioInputs.Count,DisplayCount=snapshot.Displays.Count,report.Passed,report.Attention,report.Manual,Checks=report.Checks.Select(c=>new{c.Area,c.Label,c.State}),snapshot.Warnings},LocalStore.Json));
  check(report.Checks.Any(c=>c.Id=="dns")&&report.Checks.Any(c=>c.Id=="internet")&&report.Checks.Single(c=>c.Id=="audio-heard").State=="manual","Live readiness separates DNS, HTTPS and user-confirmed audio evidence");check(report.Checks.Single(c=>c.Id=="encoder").State=="manual"&&report.Checks.Any(c=>c.Area=="Oyun / Counter-Strike 2"),"Live streaming/game checks do not claim unmeasured encoder or game performance success");
 }
}
